SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'bing.com/images/create' OR LOWER(`name`) = 'bing image creator')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Bing Image Creator', NULL, 'https://www.bing.com/images/create', NULL, NULL, 'Безкоштовний генератор зображень від Microsoft у Bing: опишіть картинку словами й отримайте кілька варіантів.', 'Free image generator from Microsoft in Bing: describe a picture in words and get several variants.', 'Bing Image Creator — інструмент Microsoft для створення зображень за текстовим описом прямо в пошуковику Bing. Потрібен лише обліковий запис Microsoft. Сервіс приймає запити кількома мовами, дає змогу редагувати й завантажувати результати. Безкоштовне використання має ліміти швидкої генерації, бонуси можна отримувати через Microsoft Rewards.', 'Bing Image Creator is Microsoft''s tool for creating images from a text description right inside Bing. All you need is a Microsoft account. It accepts prompts in several languages and lets you edit and download results. Free use has fast-generation limits, and bonuses can be earned through Microsoft Rewards.', 'Генерація зображень за текстом
Кілька варіантів за один запит
Вхід через обліковий запис Microsoft
Бонуси Microsoft Rewards', 'Text-to-image generation
Several variants per prompt
Sign-in with a Microsoft account
Microsoft Rewards bonuses', 'Усім, хто хоче безкоштовно спробувати АІ-генерацію картинок без окремої підписки.', 'Anyone who wants to try AI image generation for free without a separate subscription.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-29 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'bing.com/images/create' OR LOWER(`name`) = 'bing image creator') ORDER BY `id` LIMIT 1);
